  function navGroupedOn() { return !!(S.session && S.session.user.isManager && !liteOnly()); }
  function navKey() { var u = S.session && S.session.user; return 'bio-nav-' + (u ? u.id || u.name || '' : ''); }
  function navPrefs() { var p = null; try { p = JSON.parse(localStorage.getItem(navKey()) || 'null'); } catch (e) {} p = p || {}; p.open = p.open && !p.open.cmd && !p.open.farms ? p.open : { now: 1, map: 1 }; p.fav = (p.fav || []).slice(0, 4); return p; }
  function navSave(p) { try { localStorage.setItem(navKey(), JSON.stringify(p)); } catch (e) {} }
  /** الأقسام المتاحة للمستخدم مرتبة في المجموعات (الشاشات المخفية تختفي، وما ليس له مجموعة يدخل الإدارة قبل ترتيب المحطات) */
  function navGrouped() {
    var all = navItems(), used = { more: 1 };
    var gs = NAV_GROUPS.map(function (g) { return { k: g[0], label: g[1], icon: g[2], items: g[3].map(function (k) { var n = all.filter(function (x) { return x[0] === k; })[0]; if (n) used[k] = 1; return n; }).filter(Boolean) }; });
    var rest = all.filter(function (n) { return !used[n[0]]; }), adm = gs[gs.length - 1];
    if (rest.length) { var lg = adm.items.filter(function (n) { return n[0] === 'league'; }); adm.items = adm.items.filter(function (n) { return n[0] !== 'league'; }).concat(rest, lg); }
    return gs.filter(function (g) { return g.items.length; });
  }
