    if (!S.rcBoot) { S.rcBoot = true; var go0 = false, st0 = function () { if (go0) return; go0 = true; startApp(); }; S.rcReady = rcLoad().then(function () { rcPrefetch(); }); S.rcReady.then(st0); setTimeout(st0, 350); return; }
