    var pick = function (re) { var k = null; Object.keys(K).forEach(function (n) { if (!k && re.test(n + ' ' + K[n].label)) k = K[n]; }); return k; };
    var c = pick(/compl|التزام/), mo = pick(/mort|نافق|نفوق/);
