    var crit = (d.ews || []).length + (d.reports ? d.reports.open.length : 0);
    list.push({ label: 'أحداث حرجة مفتوحة', txt: String(crit), sub: crit ? [(d.ews || []).length ? plural(d.ews.length, 'إنذار نافق', 'إنذارات نافق') : '', d.reports && d.reports.open.length ? plural(d.reports.open.length, 'بلاغ', 'بلاغات') : ''].filter(Boolean).join(' · ') : 'لا شيء مفتوح', series: days.map(function (x) { return x.reports; }), bad: crit > 0 });
    var endToday = d.isolation.filter(function (i) { var mx = 0; Object.keys(i.until || {}).forEach(function (l) { mx = Math.max(mx, i.until[l]); }); return mx - Date.now() < 24 * 36e5; }).length;
