      return '<div class="field">' + lab + '<select id="' + id + '">' + o.map(function (x) { return '<option value="' + esc(x[0]) + '"' + (BIO_norm(x[0]) === BIO_norm(v) ? ' selected' : '') + '>' + esc(x[1]) + '</option>'; }).join('') + '</select>' + hint + '</div>';
