  var BIRD_SPECIES = ['بط بري (خضاري أو شرشير)', 'بلشون أو أبو قردان', 'نوارس', 'لقلق أبيض', 'صقور وجوارح', 'حمام', 'غربان', 'عصافير', 'سمان', 'طيور غير معروفة'];
