  var ATT_C = { 'حضور': 'var(--r-low)', 'مأمورية': 'var(--info)', 'راحة': '#8aa0b8', 'نزول': 'var(--r-mid)', 'غياب': 'var(--r-crit)', 'مرضي': 'var(--r-high)' };
  var ATT_P = { 'حضور': 'p-ok', 'مأمورية': 'p-info', 'راحة': 'p-n', 'نزول': 'p-warn', 'غياب': 'p-bad', 'مرضي': 'p-bad', 'لم تُسجَّل': 'p-n' };
  var ATT_K = ['حضور', 'مأمورية', 'راحة', 'نزول', 'مرضي', 'غياب'];
