          '<div class="field"><label for="gdV">المركبة</label><select id="gdV"><option value="">اختر المركبة</option>' + veh.map(function (v) { return '<option value="' + esc(v.id) + '"' + (v.id === G.itemId ? ' selected' : '') + '>' + esc(v.name + (v.plate ? ' · ' + v.plate : '') + ' · ' + v.id) + '</option>'; }).join('') + '</select><span class="xs muted">مركبة جديدة؟ سجلها أولاً من البوابة («تسجيل الآن») ثم أرسل لها خط السير.</span></div>' +
          '<div class="field"><label for="gdF">نقطة البداية</label><select id="gdF"><option value="">اختر</option>' + siteOptions(d.sites, G.fromId) + '</select></div>' +
          '<div class="field"><label for="gdAdd">الوجهات بالترتيب</label><select id="gdAdd"><option value="">+ أضف محطة أو موقعاً</option>' + siteOptions(d.sites.filter(function (s) { return G.stops.indexOf(s.id) < 0 && s.id !== G.fromId; })) + '</select>' +
          (G.stops.length ? '<ol class="tu-stops">' + G.stops.map(function (id, i) { return '<li><span class="n">' + (i + 1) + '</span><b>' + esc(shortSite(by[id].name)) + '</b><span class="tu-mv"><button type="button" data-a="up" data-v="' + i + '"' + (i ? '' : ' disabled') + '>▲</button><button type="button" data-a="dn" data-v="' + i + '"' + (i < G.stops.length - 1 ? '' : ' disabled') + '>▼</button><button type="button" data-a="rm" data-v="' + i + '" aria-label="حذف">✕</button></span></li>'; }).join('') + '</ol>' : '') + '</div>' +
          '<div class="grid-2" style="gap:12px"><div class="field"><label for="gdDrv">اسم السائق</label><input id="gdDrv" maxlength="60" value="' + esc(k.drv) + '"></div><div class="field"><label for="gdPh">موبايل السائق (واتساب)</label><input id="gdPh" type="tel" dir="ltr" inputmode="tel" placeholder="01xxxxxxxxx" value="' + esc(k.ph) + '"></div></div>' +
          (G.tourId ? '<p class="xs muted">' + icon('truck') + ' مرتبط بالجولة المعتمدة ' + esc(G.tourId) + '</p>' : '') +
          '<button class="btn primary big" data-a="send"' + (G.itemId && G.stops.length && G.fromId ? '' : ' disabled') + '>' + icon('send') + ' إنشاء خط السير</button><button class="btn ghost" data-a="close">إلغاء</button></div>';
