    var sc = function (v) { return v >= 90 ? 'var(--r-low)' : v >= 75 ? '#65a30d' : v >= 60 ? 'var(--r-mid)' : 'var(--r-crit)'; };
    var block = function (cat, title) {
      var L = d.list.filter(function (x) { return x.cat === cat; }); if (!L.length) return '';
      var pod = L.slice(0, 3);
      return '<div class="card"><div class="card-head"><div><span class="kick">' + monthAr(d.month) + (d.current ? ' · حتى اليوم' : '') + ' · مقارنة بشهر ' + monthAr(d.prevMonth) + '</span><h2>' + icon('trophy') + ' ' + title + '</h2></div><span class="badge">' + L.length + '</span></div>' +
        '<div class="lg-pod">' + pod.map(function (x) { return '<button type="button" class="lg-p r' + x.rank + '" data-lg="' + esc(x.id) + '"><span class="lg-medal">' + x.rank + '</span><b>' + esc(shortSite(x.name)) + '</b><span class="mono lg-s">' + x.score + '</span>' + mv(x) + '</button>'; }).join('') + '</div>' +
        '<div class="lg-list">' + L.map(function (x) { return '<button type="button" class="lg-row" data-lg="' + esc(x.id) + '"><span class="lg-rk mono">' + x.rank + '</span><span class="lg-nm"><b>' + esc(shortSite(x.name)) + '</b><span class="xs muted">' + esc(x.sector) + ' · ' + x.entries + ' دخول' + (x.flags ? ' · ' + x.flags + ' مخالفة' : '') + '</span></span><span class="lg-bar"><i style="width:' + x.score + '%;background:' + sc(x.score) + '"></i></span><b class="mono lg-sc">' + x.score + '</b>' + mv(x) + '</button>'; }).join('') + '</div></div>';
    };
    var html = d.list.length ? block('fat', 'محطات التسمين') + block('other', 'الأمهات والمعامل والمصانع') : '<div class="card"><p class="empty">' + icon('trophy') + ' لا توجد بيانات كافية لهذا الشهر بعد.</p></div>';
    html += '<div class="card"><h2>' + icon('book') + ' كيف تُحسب النقاط</h2><div class="st-how">' + [['shield', 'الالتزام عند الدخول 30%', 'دخول مطابق للقواعد من أول مرة، والاستثنائي بنصف النقاط.'], ['alert', 'الخلو من المخالفات 15%', 'كل مخالفة تخصم 15 نقطة، وكل رفض دخول 4 نقاط.'], ['pulse', 'النافق 25%', 'متوسط نسبة النافق اليومية من ملف بيانات المزارع مقارنة بالهدف.'], ['clip', 'تقارير الزيارة 15% والتدقيق 10%', 'متوسط درجات تقارير الأمن الحيوي والتدقيق الداخلي في الشهر.']].map(function (x) { return '<div><span class="ki">' + icon(x[0]) + '</span><b>' + x[1] + '</b><p>' + x[2] + '</p></div>'; }).join('') + '</div><p class="xs muted">العامل الذي لا تتوفر له بيانات لا يدخل الحساب، وتُوزَّع أوزانه على الباقي.</p></div>';
    out.innerHTML = html;
