        d.trend.map(function (t, i) { var h = t.cost / tmax * Hh; return '<rect x="' + (38 + i * bw).toFixed(1) + '" y="' + (10 + Hh - h).toFixed(1) + '" width="' + Math.max(2, bw - 2).toFixed(1) + '" height="' + Math.max(0, h).toFixed(1) + '" rx="2" class="br' + (i === n - 1 ? ' last' : '') + '"><title>' + t.day + ': ' + t.cost + ' جنيه · ' + t.qty + ' مركّز</title></rect>' + (i % Math.ceil(n / 6) === 0 || i === n - 1 ? '<text x="' + (38 + i * bw + bw / 2).toFixed(1) + '" y="' + (Hh + 24) + '" class="ax" text-anchor="middle">' + t.day.slice(5).replace('-', '/') + '</text>' : ''); }).join('') + '</svg></div></div></div>';
