    var load = function () { rkWindGrid(map.getBounds().pad(0.2), lvl).then(function (v) { fl.set(v); fl.src = 'grid'; var b = map.getContainer().closest('.rk'); if (b) b.classList.add('rk-wgrid'); }).catch(function () {}); };
