      el.disabled = true; remote('epiReport', [S.session.pin, r]).then(function () { closeSheet(); toast('سُجلت البؤرة وأُعيد حساب الخطر'); viewEpi([S.epi ? S.epi.days : 90]); }).catch(function (e) { el.disabled = false; $('erErr').textContent = errText(e); });
