      el.disabled = true; remote('epiLab', [S.session.pin, r]).then(function () { closeSheet(); toast(res === 'إيجابي' ? 'سُجلت النتيجة الإيجابية كبؤرة مؤكدة وأُعيد حساب الخطر' : 'حُفظت النتيجة السلبية في السجل'); viewEpi([S.epi ? S.epi.days : 90]); }).catch(function (e) { el.disabled = false; $('lbErr').textContent = errText(e); });
