  /** قراءة ملف CSV (يدعم الفاصلة والفاصلة المنقوطة والتاب والاقتباس) */
  function csvRows(t) {
    t = String(t || '').replace(/^﻿/, ''); var first = t.split('\n')[0], dl = (first.split(';').length > first.split(',').length) ? ';' : (first.split('\t').length > first.split(',').length ? '\t' : ',');
    var rows = [], row = [], f = '', q = false;
    for (var i = 0; i < t.length; i++) { var c = t[i];
      if (q) { if (c === '"') { if (t[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
      else if (c === '"') q = true; else if (c === dl) { row.push(f); f = ''; } else if (c === '\n') { row.push(f); rows.push(row); row = []; f = ''; } else if (c !== '\r') f += c; }
    if (f || row.length) { row.push(f); rows.push(row); }
    return rows.filter(function (r) { return r.join('').trim(); });
  }
  function epiIsoDate(v) {
    v = String(v || '').trim(); var m;
    if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(v))) return m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2);
    if ((m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/.exec(v))) { var a = +m[1], b = +m[2], dd = a > 12 ? a : b > 12 ? b : a, mm = a > 12 ? b : b > 12 ? a : b; return m[3] + '-' + ('0' + mm).slice(-2) + '-' + ('0' + dd).slice(-2); }
    var t = Date.parse(v); return isNaN(t) ? '' : new Date(t).toISOString().slice(0, 10);
  }
  /** تحويل صفوف ملف EMPRES-i+ لبؤر */
  function epiFaoRows(rows) {
    if (rows.length < 2) return [];
    var hd = rows[0].map(function (h) { return String(h).toLowerCase().replace(/[^a-z0-9]/g, ''); });
    var col = function (re) { for (var i = 0; i < hd.length; i++) if (re.test(hd[i])) return i; return -1; };
    var C = { id: col(/^(eventid|id|outbreakid)$/), disease: col(/^disease/), agent: col(/serotype|subtype|agent|strain/), country: col(/^country/), place: col(/locality|location|admin2|admin1|region/), lat: col(/^lat/), lng: col(/^(lon|lng)/), date: col(/observ|startdate|onset/), date2: col(/reportdate|date/), species: col(/species/), cases: col(/^(cases|sumcases)/), deaths: col(/death/), status: col(/status/) };
    if (C.lat < 0 || C.lng < 0 || C.disease < 0) return null;
    var v = function (r, k) { return C[k] >= 0 ? String(r[C[k]] == null ? '' : r[C[k]]).trim() : ''; };
    return rows.slice(1).map(function (r) { return { id: v(r, 'id'), disease: v(r, 'disease'), agent: v(r, 'agent'), country: v(r, 'country'), place: v(r, 'place'), lat: v(r, 'lat'), lng: v(r, 'lng'), date: epiIsoDate(v(r, 'date') || v(r, 'date2')), species: v(r, 'species'), cases: v(r, 'cases'), deaths: v(r, 'deaths'), status: v(r, 'status') }; })
      .filter(function (x) { return x.lat && x.lng && !isNaN(parseFloat(x.lat)) && !isNaN(parseFloat(x.lng)); });
  }
  function epiFaoSheet(d) {
    var got = null;
    openSheet('<div class="sheet-head sh-brand"><h2>' + icon('upload') + ' استيراد بؤر FAO EMPRES-i+</h2><span class="small">الفاو لا تتيح واجهة بيانات مفتوحة للتحميل الآلي، فيُصدَّر الملف من موقعها ويُرفع هنا. وسم الثقة: «موثق دولياً».</span></div><div class="sheet-body">' +
      '<ol class="e20-steps"><li>افتح <a href="https://empres-i.apps.fao.org/" target="_blank" rel="noopener">EMPRES-i+</a> ثم قائمة الأحداث المرضية (Disease events).</li><li>اختر المرض (إنفلونزا الطيور، النيوكاسل) والدول والفترة.</li><li>صدّر النتيجة بصيغة CSV وارفع الملف هنا. البؤر المكررة لا تُضاف مرتين.</li></ol>' + '<div class="infobox small">' + icon('folder') + ' <span><b>أسهل وتلقائي:</b> احفظ ملف التصدير في ' + (d.fao && d.fao.url ? '<a href="' + esc(d.fao.url) + '" target="_blank" rel="noopener">مجلد Drive «' + esc(d.fao.name || 'رادار الوبائيات - ملفات FAO') + '»</a>' : 'مجلد Drive «رادار الوبائيات - ملفات FAO» (يُنشأ في حساب المنظومة مع أول تحديث)') + ' من الكمبيوتر أو الموبايل، والمنظومة تستورده وحدها كل 6 ساعات.</span></div>' +
      '<div class="field"><label for="faF">ملف CSV</label><input id="faF" type="file" accept=".csv,text/csv,text/plain"></div><div id="faPrev" class="small"></div><div class="login-err" id="faErr" role="alert"></div>' +
      '<button class="btn primary big" data-a="save" id="faGo" disabled>' + icon('upload') + ' استيراد</button><button class="btn ghost" data-a="close">إلغاء</button></div>', function (a, el) {
      if (a === 'close') return closeSheet(); if (a !== 'save' || !got) return;
      el.disabled = true; el.innerHTML = '<span class="spin"></span> جارٍ الاستيراد';
      remote('epiImport', [S.session.pin, got]).then(function (r) { closeSheet(); toast('أُضيفت ' + r.added + ' بؤرة من ' + r.total + ' صف'); viewEpi([S.epi ? S.epi.days : 90]); }).catch(function (e) { el.disabled = false; el.innerHTML = icon('upload') + ' استيراد'; $('faErr').textContent = errText(e); });
    });
    $('faF').onchange = function () {
      var f = this.files && this.files[0]; got = null; $('faGo').disabled = true; $('faErr').textContent = ''; $('faPrev').textContent = ''; if (!f) return;
      var rd = new FileReader(); rd.onload = function () {
        var list = epiFaoRows(csvRows(rd.result));
        if (!list) { $('faErr').textContent = 'لم أجد أعمدة المرض وخط العرض وخط الطول في الملف. تأكد أنه ملف التصدير من EMPRES-i+.'; return; }
        if (!list.length) { $('faErr').textContent = 'الملف لا يحتوي صفوفاً بإحداثيات.'; return; }
        got = list; $('faGo').disabled = false;
        var cs = {}; list.forEach(function (x) { cs[x.country || '—'] = 1; });
        $('faPrev').innerHTML = '<div class="infobox small">' + icon('check') + ' <span>' + list.length + ' صف بإحداثيات من ' + Object.keys(cs).length + ' دولة · مثال: ' + esc(list[0].disease + ' · ' + (list[0].place || list[0].country) + ' · ' + list[0].date) + '</span></div>';
      }; rd.readAsText(f);
    };
  }
