        '<div class="s21-row xs"><span>عمر ' + (c.age || 0) + ' يوم من ' + to + '</span><span>البيع المتوقع ' + esc(d21(c.expSaleFrom, true)) + ' ← ' + esc(d21(c.expSaleTo, true)) + '</span></div>' +
        (c.saleFrom ? '<div class="s21-row xs"><span class="warn-t">' + icon('out') + ' البيع بدأ ' + esc(d21(c.saleFrom, true)) + '</span><span>متوقع انتهاؤه ' + esc(d21(c.expSaleTo, true)) + '</span></div>' : '') +
        (c.planned ? '<div class="xs warn-t">' + icon('calendar') + ' التسكين بدأ ' + esc(d21(c.first, true)) + ' حسب خطة التسكين: ' + n0(c.placed) + ' كتكوت مخطط حتى اليوم. يظهر الرصيد الفعلي مع أول ملف بيانات فيه الدورة</div>' : '') +
        (c.sources ? '<div class="xs muted">مصادر الكتاكيت: ' + esc(c.sources) + (c.placed && !c.planned ? ' · مسكّن ' + n0(c.placed) : '') + '</div>' : '') + '</div>';
