    pl.forEach(function (p) { p.hits.forEach(function (h) { A.push({ lv: h.km < 2 ? 'crit' : 'high', ic: 'wind', t: 'الرياح تحمل غبار ' + p.why + ' من ' + nm(p.s.id) + ' نحو ' + nm(h.id), s: h.km + ' كم · رياح ' + Math.round(p.spd) + ' كم/س. أوقف الحركة بينهما وأغلق الفتحات المواجهة', at: h.id, lens: 'air' }); }); });
