    (d.epi || []).filter(function (e) { return e.km <= 50; }).forEach(function (e) { A.push({ lv: e.km <= 10 ? 'crit' : 'high', ic: 'siren', t: 'بؤرة على بعد ' + e.km + ' كم: ' + (e.dis || { hpai: 'إنفلونزا الطيور عالية الضراوة', lpai: 'إنفلونزا الطيور منخفضة الضراوة', nd: 'النيوكاسل' }[e.kind] || e.kind), s: e.place + ' · منذ ' + e.days + ' يوم · ' + e.src, ll: [e.lat, e.lng], lens: 'risk' }); });
    (d.trips || []).filter(function (t) { return t.alerts; }).forEach(function (t) { A.push({ lv: 'high', ic: 'truck', t: 'تنبيه رحلة: ' + t.item, s: t.alerts + ' تنبيه · إلى ' + (t.to || '—'), ll: [t.lat, t.lng], lens: 'flow' }); });
    (d.geoWarn || []).forEach(function (g) { A.push({ lv: 'mid', ic: 'pin', t: 'إحداثيات مكررة: ' + nm(g.a) + ' و' + nm(g.b), s: 'المسافة ' + g.m + ' م. صحّح الإحداثيات من جدول المواقع', at: g.a, lens: 'risk' }); });
    d.sites.filter(function (s) { return s.gt && s.gt.state === 'prep' && s.gt.day > s.gt.total; }).forEach(function (s) { A.push({ lv: 'mid', ic: 'calendar', t: nm(s.id) + ': تجاوز موعد التسكين المحسوب', s: 'اليوم ' + s.gt.day + ' بعد البيع', at: s.id, lens: 'cycle' }); });
