  var THEMES = { auto: ['تلقائي', 'auto', 'يتبع إعداد الجهاز'], light: ['فاتح', 'sun', 'هوية «التوأم الرقمي»'], dark: ['داكن', 'moon', 'هوية «مركز القيادة»'] };
  function themeGet() { try { var t = localStorage.getItem('bio_theme'); return THEMES[t] ? t : 'auto'; } catch (e) { return 'auto'; } }
  function themeApply(t) {
    var r = document.documentElement; if (t === 'light' || t === 'dark') r.setAttribute('data-theme', t); else r.removeAttribute('data-theme');
    var dark = t === 'dark' || (t === 'auto' && window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches);
    var m = document.querySelector('meta[name="theme-color"]'); if (m) m.setAttribute('content', dark ? '#0d0d0e' : '#262628');
  }
  function themeSet(t) {
    try { localStorage.setItem('bio_theme', t); } catch (e) {}
    themeApply(t); themeBtnPaint();
    document.querySelectorAll('[data-theme-pick]').forEach(function (b) { b.classList.toggle('on', b.dataset.themePick === t); });
    toast('المظهر: ' + THEMES[t][0] + ' · ' + THEMES[t][2]);
  }
  function themeCycle() { var t = themeGet(); themeSet(t === 'auto' ? 'light' : t === 'light' ? 'dark' : 'auto'); }
  function themeBtnPaint() { var b = $('themeBtn'); if (!b) return; var t = themeGet(); b.innerHTML = icon(THEMES[t][1]); b.title = 'المظهر: ' + THEMES[t][0] + ' (اضغط للتبديل)'; b.setAttribute('aria-label', b.title); }
