    var fac = '<div class="card"><div class="card-head"><h2>' + icon('gauge') + ' 2. معاملات النوع والقطاع</h2></div><div class="iso-facs">' +
      kinds.map(function (k) { return '<div class="iso-fac"><span class="iso-fi">' + icon(k[2]) + '</span><div><b>' + k[1] + '</b><small>' + (k[0] === 'person' ? 'موظف، عامل، زائر، سائق' : k[0] === 'vehicle' ? 'سيارات ونقل وجرارات' : 'أدوات ومعدات متنقلة') + '</small></div>' + st('kind.' + k[0], F.kind[k[0]], 0, 10, 0.25, '×') + '</div>'; }).join('') +
      '<div class="iso-fac"><span class="iso-fi">' + icon('route') + '</span><div><b>فرق الانتقال بين قطاعين</b><small>يُضاف لو الشخص جاي من قطاع تاني (مثلاً من ريجوا للواحات)</small></div>' + st('cross', Number(F.cross) || 0, 0, 240, 6, 'س') + '</div>' +
      '<div class="iso-fac"><span class="iso-fi">' + icon('clock') + '</span><div><b>الحد الأدنى لأي عزل</b><small>لو المعادلة طلعت أقل منه يُرفع له (0 = بدون)</small></div>' + st('minH', Number(F.minH) || 0, 0, 240, 6, 'س') + '</div></div></div>';
