  function isoExRedraw() { var c = $('isoEx'); if (!c) return; var t = document.createElement('div'); t.innerHTML = isoExCard(); var w = $('isoXWhy') ? $('isoXWhy').value : ''; c.replaceWith(t.firstChild); if ($('isoXWhy')) $('isoXWhy').value = w; isoExBind(); }
