  /* ============================ الإصدار 26: المخازن والأرصدة، تقييمات موظفي الإدارة، طباعة التقارير ============================ */
  var ROLE_SUP = 'مشرف أمن حيوي', ROLE_OFF = 'مسؤول أمن حيوي';
  function myRole() { var u = S.session && S.session.user; return u ? String(u.role || '') : ''; }
