    var pt = function (e) { var r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * cv.width / r.width, (e.clientY - r.top) * cv.height / r.height]; };
    cv.onpointerdown = function (e) { cv.setPointerCapture(e.pointerId); last = pt(e); e.preventDefault(); };
    cv.onpointermove = function (e) { if (!last) return; var p = pt(e); ctx.beginPath(); ctx.moveTo(last[0], last[1]); ctx.lineTo(p[0], p[1]); ctx.stroke(); last = p; drawn = true; };
    cv.onpointerup = cv.onpointercancel = function () { last = null; };
