  /** يقص الفراغ حول التوقيع ويصغره لحد ما يبقى أقل من 40 ألف حرف */
  function awTrim(cv) {
    var c = cv.getContext('2d'), w = cv.width, h = cv.height, px = c.getImageData(0, 0, w, h).data, x0 = w, y0 = h, x1 = 0, y1 = 0;
    for (var y = 0; y < h; y++) for (var x = 0; x < w; x++) if (px[(y * w + x) * 4 + 3] > 20) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
    if (x1 <= x0) return '';
    x0 = Math.max(0, x0 - 8); y0 = Math.max(0, y0 - 8); x1 = Math.min(w, x1 + 8); y1 = Math.min(h, y1 + 8);
    for (var sc = 1; sc > 0.2; sc -= 0.15) {
      var o = document.createElement('canvas'); o.width = Math.round((x1 - x0) * sc * 0.6); o.height = Math.round((y1 - y0) * sc * 0.6);
      o.getContext('2d').drawImage(cv, x0, y0, x1 - x0, y1 - y0, 0, 0, o.width, o.height);
      var u = o.toDataURL('image/png'); if (u.length < 40000) return u;
    }
    return '';
  }
